const _rx = s => new RegExp(s);

export function cleanMerchant(raw) {
  let t = ' ' + String(raw || '').toUpperCase() + ' ';
  t = t.replace(/^ (SQ \*|TST\*|PY \*|SP 0624 |SP |FSP\*|SSP\*|PB \*|WP\*|JFI\*|PT |WL \*|FH\*|PHR\*|INTUIT \*)/, ' ');
  t = t.replace(/[A-Z0-9.-]*\.(COM|ORG|NET|IO|EDC)[A-Z]*/g, ' ');
  t = t.replace(/\bWWW\b/g, ' ');
  t = t.replace(/PHONE NUMBER:.*/, ' ');
  t = t.replace(/\b\d{3}-\d{3}-?\d{3,4}\b/g, ' ');
  t = t.replace(/\b\d{3}-\d{7}\b/g, ' ');
  t = t.replace(/\b1-800-\d*/g, ' ');
  t = t.replace(/#\s*\d+/g, ' ');
  t = t.replace(/\bF\d{4}\b/g, ' ');
  t = t.replace(/\b\d{3,6}\b/g, ' ');
  t = t.replace(/\s+(VA|CA|NJ|GA|TN|NC|FL|WA|MD|DC|MI|SC|WV|NY|OH|AR|OK|MS|KY|PA|TX)\s*$/, ' ');
  t = t.replace(/\([^)]*\)/g, ' ');
  return t.replace(/\s+/g, ' ').trim();
}

function _firstMatch(text, rules) {
  for (const [pat, ...rest] of rules) {
    if (_rx(pat).test(text)) return rest;
  }
  return null;
}

export function normalizeMerchant(raw) {
  const rawU = String(raw || '').toUpperCase();
  let hit = _firstMatch(rawU, RAW_ALIASES);
  if (hit) return hit[0];
  const cleaned = cleanMerchant(raw);
  hit = _firstMatch(cleaned, ALIASES);
  if (hit) return hit[0];
  const fb = cleaned.toLowerCase().replace(/\b\w/g, c => c.toUpperCase());
  return (fb || String(raw).trim()).slice(0, 42);
}

export function categorizeTransaction(merchant, raw) {
  const text = merchant.toUpperCase() + ' | ' + cleanMerchant(raw) + ' | ' + String(raw || '').toUpperCase();
  const hit = _firstMatch(text, CATEGORY_RULES);
  return hit ? { category: hit[0], subcategory: hit[1] } : { category: 'Uncategorized', subcategory: '' };
}
